"""Local review page and grouped measurements, with no changes to demo files."""
from pathlib import Path
import json,sys,html
out=Path(sys.argv[1]);m=json.loads((out/'metrics.json').read_text());poses=list(m['poses']);rows=[]
for name,r in m['pose_decisions'].items():rows.append('<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in [name,f"{r['p99']:.4f}",r['thin'],f"{r['neck_out_increment_mm']:.3f}",f"{r['hair_jaw_in_increment_mm']:.3f}",'対象外' if r['excluded'] else '合格' if r['numeric_pass'] else '不合格'])+'</tr>')
page='''<!doctype html><html lang="ja"><meta charset="utf-8"><title>lowpoly10 の確認</title><style>body{font:16px/1.6 system-ui;margin:24px;background:#f6f6f6;color:#222}h1{font-size:24px}button,select{font:inherit;padding:8px}canvas{display:block;max-width:100%;height:auto;background:white}section{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}table{border-collapse:collapse;background:white}td,th{padding:6px 12px;text-align:left;border-bottom:1px solid #ccc}img{max-width:100%}a{color:#1460aa}</style><h1>工程6・10回目</h1><p>胸固定により襟の折れは解消しました。首の段と髪の裏の小片が残り、数値と輪郭も未達です。</p><label>ポーズ <select id="pose"></select></label> <button id="prev">前</button> <button id="next">次</button> <label>拡大の向き <select id="angle"><option>0</option><option selected>25</option><option>90</option></select></label><p id="status" role="status"></p><section><figure><figcaption>デモの画角・1280×800</figcaption><canvas id="demo" width="1280" height="800"></canvas></figure><figure><figcaption>首の拡大・同じ姿勢</figcaption><canvas id="neck" width="1280" height="800"></canvas></figure></section><p><a href="demo-frames.png">全フレーム</a> / <a href="neck-frames.png">首の拡大一覧</a> / <a href="arm-frames.png">腕上げ</a> / <a href="metrics.json">測定値</a> / <a href="head-inventory.json">頭の部位・高さ別内訳</a> / <a href="log.md">作業記録</a></p><table><tr><th>ポーズ</th><th>P99</th><th>つぶれ</th><th>首外増分mm</th><th>髪あご内増分mm</th><th>数値</th></tr>ROWS</table><script>const poses=POSES;const p=document.querySelector('#pose'),a=document.querySelector('#angle');for(const name of poses){const o=document.createElement('option');o.textContent=name;p.append(o)}async function load(id,src){const i=new Image();i.src=src;await i.decode();const c=document.getElementById(id);c.getContext('2d').drawImage(i,0,0);return{src,width:i.width,height:i.height}}window.renderReview=async()=>{window.reviewReady=false;const name=p.value;window.reviewImages=await Promise.all([load('demo','demo-'+name+'.png'),load('neck','neck-close-'+name+'-'+a.value+'.png')]);document.getElementById('status').textContent=name+' / '+a.value+'°';window.reviewReady=true;};p.onchange=a.onchange=window.renderReview;document.querySelector('#prev').onclick=()=>{p.selectedIndex=(p.selectedIndex+poses.length-1)%poses.length;window.renderReview()};document.querySelector('#next').onclick=()=>{p.selectedIndex=(p.selectedIndex+1)%poses.length;window.renderReview()};window.renderReview();</script></html>'''.replace('ROWS',''.join(rows)).replace('POSES',json.dumps(poses));(out/'review.html').write_text(page)
